DE_BETA_A2 = {
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_0'): 'Übrigens, deine Leute, die die Insel verlassen\nhaben -- die Ashigumo. Wie sind die so?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_1'): 'Für uns sind ihr Götter der Hauptstadt und\ndie Kinder der Menschen in Form und Persönlichkeit\nunglaublich verschieden.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_10'): 'So beruhigend das auch ist, ich kann nicht\numhin, eine gewisse Melancholie zu spüren, dich so zurückzuhalten.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_11'): 'Mach dir keine Sorgen. Das ist meine Wahl.\nUnd Tauemons Wort nach hast du mir ebenso\ngeholfen, wie ich dir geholfen habe.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_2'): 'Mit anderen Worten: Im Vergleich zu euch gibt\nes bei den Mitgliedern unseres Volkes weniger\noffensichtliche Unterschiede.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_3'): 'Und wir alle tun lieber alles selbst.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_4'): 'Also verkehrt ihr nicht viel\nmiteinander?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_5'): 'Vielleicht aus deiner Sicht.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_6'): 'Aber das Verschwinden ihrer Gegenwart\nvon der Insel missfällt mir dennoch.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_7'): 'Du hast bereits mehr als genug für uns getan.\nDu kannst gern losgehen und nach ihnen suchen,\nwenn du möchtest.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_8'): 'Eines Tages ja.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AboutAshigumo_9'): 'Solange die Dämonen diese Insel durchstreifen,\nverlasse ich sie nicht.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_0'): 'Ashigumo. Wir kennen uns schon\nseit einiger Zeit.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_1'): 'Warum kommst du nicht gelegentlich mit uns\nam Herd ein Mahl einnehmen?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_10'): 'Ich bin beeindruckt, dass du Kinta trotzdem\nin die Wege des Schmiedens unterweisen konntest.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_11'): 'Mmrgh...',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_12'): 'Prinzessin, du bist hochgradig unhöflich!',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_13'): 'Ahaha... Entschuldige, entschuldige.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_14'): 'Wenn der Herd nicht in Frage kommt, solltest du\nauf der Veranda mit mir einen Drink nach dem Essen nehmen.\nDas läge dir mehr, nehme ich an?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_15'): 'Ja. Das kann ich.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_2'): '...',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_3'): 'Du willst nicht?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_4'): 'Das ist ziemlich kalt...',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_5'): '...Es ist nicht, dass ich nicht möchte.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_6'): 'Dann gibt es einen anderen Grund, warum du nicht kannst?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_7'): '...Feuer bringt mich auf die Pauschale.\nIch könnte mich da drinnen nie entspannen.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_8'): 'Pffft... Pfffhahaha!',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_AfraidFire_9'): 'SO lag es also daran. Es ist schwer, sich vorzustellen,\ndass jemand so abweisend wie du eine solche\nSchwäche hat, und dennoch!',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_0'): 'Du kennst meinen Vater und meine Mutter,\noder?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_1'): 'Was für Götter waren sie,\naus deiner Sicht?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_10'): 'Heh... „Erfreulich" fängt nicht einmal an,\nalles zu beschreiben, was geschah.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_11'): 'Sakuna. Du verträgst dich gut mit der\nderzeitigen Kamuhitsuki, richtig?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_12'): 'Nun, behalte es bei. Ich bin müde vom Krieg\nmit der Hauptstadt.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_13'): 'Haha. Fürchte nichts.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_14'): 'So erhaben und unbezwingbar ich auch bin,\nso gesetzlos bin ich nicht, Lady Kamuhitsuki zu widersprechen.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_15'): 'Mir fällt es immer noch schwer zu glauben,\ndass mein Vater sich so etwas traute.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_16'): 'Ich erinnere mich, dass du damals weitaus\ngrimmiger warst, vertraute Klinge.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_17'): 'Lassen wir... diese Erinnerung aus.\nMeine Rolle ist nun nur noch die einer\nzuverlässigen Hüterin der Prinzessin.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_18'): 'Oho...? Jetzt MUSS ich mehr hören.\nVielleicht erzählst du mir abends beim Drink davon.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_19'): 'Oooh, Prinzessin...',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_2'): 'Toyohana rettete mein Volk vor Krankheit.\nSie war einfühlsam und weis und stellte andere\nüber sich selbst.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_3'): 'Wenn es um Reis ging, war sie\njedoch...eigensinnig.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_4'): 'Sie hat reichlich Schrollen zum Thema geschrieben...\nUnd mein Vater?',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_5'): 'Er war ein unbeherrschter Mann. Wann immer\netwas missfiel, fing er sofort an,\nDinge zu werfen.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_6'): 'Uof... So hatte ich es mir gedacht.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_7'): 'Jedoch hatte er unglaubliche Kraft\nund eine bestimmte magnetische Ausstrahlung.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_8'): 'Wir stritten eine Reihe mal mit ihm,\num später zu erkennen, dass wir alle\nnach demselben suchten.',
    ('Text/Event/Mura/Soto/Ashigumo.csvtxt#beta', 'English#c:SubEvent_Parent_9'): 'Rückblickend war das eine recht erfreuliche\nZeit.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_0'): 'Du sonnst dich also, Tama?',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_1'): 'Warum kommst du nicht dazu, Prinzessin?\nEs fühlt sich himmlisch an.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_10'): 'Du bist so ein alter Mann, Tama...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_2'): '...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_3'): '*gähn*',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_4'): 'So als Müßiggänger zu liegen lässt meinen\nGedanken schweifen.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_5'): 'Es ist gut, sich ab und zu zu entspannen.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_6'): '*gähn*',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_7'): '...Ah! Oh nein. So werden wir den ganzen\nTag hier auf der Veranda liegend verbringen.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_8'): '*schnarch...* *schnaaarch...*',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Nonbiri_9'): 'Ein Weilchen länger schadet wohl nicht.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_0'): 'Ich verstehe... Ich hätte nie gedacht, dass\nToyohana in der Hauptstadt\nverschwinden würde.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_1'): 'In der Tat. Und dennoch ist Yanato noch immer\nnicht geeint.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_10'): 'Das ist gefährliche Arbeit. Hüte dich, dich nicht\nabzuknacken. So viel kannst du allein\nnun einmal nicht erreichen.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_11'): '...Ich verstehe den Hinweis. Takeribis Tochter\nist nicht so stark wie ihr Vater, auch nicht so\nvertrauenswürdig wie ihre Mutter.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_12'): 'Du willst, dass ich mich auf so jemanden verlasse?',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_13'): 'Mmrgh... Ich gebe zu, sie hatte eine behütete,\nbeschauliche Erziehung, aber...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_14'): 'Ich habe noch immer Vertrauen in sie. Bitte,\nbehalt sie im Auge und schau, wie sie besser wird.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_15'): 'Hm... In Ordnung. Ich werde sehen, was sie zu bieten hat.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_16'): 'Danke. Ich hoffe, du hilfst weiterhin.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_2'): 'Das Volk zu vereinen war ein bewundernswertes Ziel,\naber die vorherige Lady Kamuhitsuki\nhat viel zu viele Kriege entfacht.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_3'): 'Lady Toyohana wurde vielleicht von kriegerischen\nGöttern in der Hauptstadt entführt.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_4'): 'Und Takeribi sucht noch immer nach ihr?',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_5'): '...Ich habe keine Ahnung, wohin seine Suche geführt hat.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_6'): 'Was dir, Ashigumo, danach widerfahren ist,\nist wahrhaft herzzerreißend. Glück und Pech\ngehen wohl oft Hand in Hand.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_7'): '...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_8'): 'Was beabsichtigst du nun zu tun?\nWirst du aufbrechen, um nach deinem Volk zu suchen?',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Sonogo_9'): 'Nein. Ich werde diese Insel nicht den Dämonen\nüberlassen. Ich muss jeden von ihnen töten, den ich\nkann, als Opfergabe für die Verstorbenen.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_0'): 'Du bist allein? Das ist ungewöhnlich.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_1'): 'Ah, bist du es.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_10'): 'Seine Unbedachtsamkeit beeinflusste mich sehr.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_11'): 'Aber nun... es ist, als hätte selbst mein\nHerz irgendwie gealtert.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_12'): 'Es ist, weil du etwas gefunden hast, das du\nbeschützen willst. Sowohl du als auch Sakuna.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_13'): 'Du auch.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_14'): '...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_15'): 'Du musst nicht schüchtern sein. Das ist\nauch nicht deine Art. Ho ho ho...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_16'): 'Mmrgh...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_17'): 'Vor uns liegt noch eine lange Zukunft,\nAshigumo. Lass uns gemeinsam sehen,\nwelche Horizonte erwarten.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_2'): '...Ich habe Sakuna falsch eingeschätzt.\nDu hattest recht mit ihr.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_3'): 'Ho ho ho... Ich kann es nun endlich zugeben,\naber ich war mir auch nicht völlig sicher.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_4'): 'Ich weiß.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_5'): 'Du warst es, was? Und dennoch hast du ihr\ngeholfen, trotz deines mürrischen Wesens.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_6'): 'Vielleicht, weil sie anders ist als ihresgleichen...\nWie du und ich.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_7'): 'Alles, was ich bisher tat, tat ich ziellos:\nDämonen töten; mein Zuhause beschützen;\nauf Takeribi, Toyohana und\nmein Volk warten...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_8'): 'Meine Güte. Ich hätte nie gedacht, dass du\ndich so öffnen würdest. Es scheint, die Prinzessin\nist nicht die einzige, die sich verändert hat.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Tagai_9'): 'Wenn ich mich recht entsinne, warst du selbst\nfrüher, als Takeribi dich führte, übereifrig,\nDämonen zu schlagen.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_0'): 'Mmrgh... „Donnernde Gewalt..."',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_1'): 'Donnernde Gewalt...?',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_10'): 'Prinzessin...',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_11'): 'I-Ich bekomme nicht das Ganze heraus.\nEs bleibt bei „Donnernde Gewalt".',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_2'): 'Ein schneller, aber wirkungsvoller Schlag, wie ein\nBlitz... Du hast wieder eine beeindruckende\nTechnik ersonnen, Prinzessin.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_3'): 'Der Name gefällt mir nicht ganz.\nEr wirkt zu...offensichtlich.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_4'): 'Meinst du nicht, er sollte einen längeren,\nbeeindruckenderen Namen haben?',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_5'): 'Prinzessin, einer Technik einen schwungvollen\nNamen zu geben, macht sie -- oder dich -- nicht stärker.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_6'): 'Ja, aber sollte es nicht sofort den Gedanken\nwecken: „Kein gewöhnlicher Gott hätte gegen\ndas hier eine Chance"?',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_7'): 'Vielleicht, wenn ich ein paar Worte vorausschicke?\n„Merkt euch, ihr fernen Feinde. Denn ich, Prinzessin\nSakuna, Tochter von Kriegs- und Erntegöttin zugleich,\nwerde..."',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_8'): '*seufz* Ist das eine Art Samurai-Nachäfferei,\ndie du dir von Tauemon abgeschaut hast?\nIch hoffe, die Dämonen warten geduldig, bis du fertig bist.',
    ('Text/Event/Mura/Soto/Tama.csvtxt#beta', 'English#c:SubEvent_Waza_9'): '„Bushin-Yuchi-Überattacke-Super-Ballistischer\nDonnerbeschuss..."',
}

